import React, { useEffect, useRef, useState } from 'react';
import { useStore } from './store.jsx';
import { money } from './shop.js';
import { csv, dateLabel, paymentLabels, productImage, report, statusLabels, toCents } from './domain.js';
import './admin.css';

const menu = [['overview','Visão geral','grid'],['products','Produtos','shirt'],['inventory','Estoque','box'],['orders','Pedidos','bag'],['customers','Clientes','users'],['coupons','Cupons','tag'],['finance','Financeiro','wallet'],['reports','Relatórios','chart'],['media','Imagens','image'],['settings','Configurações','settings']];
function I({name,size=20}) { const paths={grid:<><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,shirt:<path d="m8 3-5 3 3 5 2-1v11h8V10l2 1 3-5-5-3c-1 3-7 3-8 0Z"/>,box:<><path d="m12 2 10 5-10 5L2 7l10-5ZM2 7v10l10 5 10-5V7M12 12v10M7 4.5l10 5"/></>,bag:<><path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/></>,users:<><circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8M19 15a6 6 0 0 1 3 6"/></>,tag:<><path d="m3 3 9 1 9 9-8 8-9-9-1-9Z"/><circle cx="8" cy="8" r="1"/></>,wallet:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 7V4l14-2v3M15 11h6v5h-6Z"/></>,chart:<><path d="M3 3v18h18M7 16v-4M12 16V8M17 16V4"/></>,image:<><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/></>,settings:<><circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/></>,plus:<path d="M12 4v16M4 12h16"/>,search:<><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></>,arrow:<path d="M4 12h16M14 6l6 6-6 6"/>,close:<path d="m6 6 12 12M6 18 18 6"/>,download:<><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></>,upload:<><path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/></>,check:<path d="m4 12 5 5L20 6"/>,alert:<><path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/></>,edit:<><path d="m15 3 6 6L9 21H3v-6L15 3ZM12 6l6 6"/></>,more:<><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></>,logout:<><path d="M9 3H3v18h6M9 12h13m-5-5 5 5-5 5"/></>,menu:<path d="M3 6h18M3 12h18M3 18h18"/>}; return <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]||paths.grid}</svg>; }
function Button({children,kind='primary',icon,...props}) { return <button className={`ad-button ${kind}`} {...props}>{icon&&<I name={icon} size={17}/>} {children}</button>; }
function Badge({value}) { return <span className={`ad-badge ${value}`}>{statusLabels[value]||value}</span>; }
function Field({label,children,hint,...props}) { return <label className="ad-field"><span>{label}</span>{children||<input {...props}/>} {hint&&<small>{hint}</small>}</label>; }
function Form({children,onSubmit,label='Salvar',busy:extraBusy=false}) { const [error,setError]=useState(''); const {busy}=useStore(); return <form className="ad-form" onSubmit={async e=>{e.preventDefault();setError('');try{await onSubmit();}catch(e){setError(e.message);}}}>{children}{error&&<div className="ad-error" role="alert"><I name="alert"/>{error}</div>}<div className="ad-form-footer"><span>Revise os dados antes de salvar.</span><Button type="submit" disabled={busy||extraBusy} icon="check">{busy||extraBusy?'Salvando…':label}</Button></div></form>; }
function Modal({title,subtitle,children,onClose,wide=false}) { const ref=useRef(null); useEffect(()=>{ref.current.showModal();const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=old;};},[]);return <dialog ref={ref} className={`ad-modal ${wide?'wide':''}`} onCancel={e=>{e.preventDefault();onClose();}} aria-labelledby="ad-modal-title"><div className="ad-modal-head"><div><span className="ad-overline">{subtitle||'GRIFF CASUAL / GESTÃO'}</span><h2 id="ad-modal-title">{title}</h2></div><button type="button" className="ad-icon" onClick={onClose} aria-label="Fechar janela"><I name="close"/></button></div><div className="ad-modal-content">{children}</div></dialog>; }
function Empty({icon='box',title='Nada por aqui ainda',text='Seus registros aparecerão aqui.',children}) { return <div className="ad-empty"><span><I name={icon} size={30}/></span><h3>{title}</h3><p>{text}</p>{children}</div>; }
function download(name,content,type='text/csv;charset=utf-8') { const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function Pager({page,setPage,total,size=10}) {const pages=Math.max(1,Math.ceil(total/size));return <div className="ad-pager"><span>{total} registros · página {page} de {pages}</span><div><button disabled={page<=1} onClick={()=>setPage(page-1)}>Anterior</button><button disabled={page>=pages} onClick={()=>setPage(page+1)}>Próxima</button></div></div>;}
function Filter({query,setQuery,placeholder='Buscar…',children}) { return <div className="ad-filters"><label className="ad-search"><I name="search" size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder} aria-label={placeholder}/></label>{children}</div>; }

function ProductForm({product,onSave}) {
  const store=useStore(); const [form,setForm]=useState(()=>({name:'',sku:`GRF-${Date.now().toString().slice(-6)}`,category:store.state.categories[0]||'',collection:'Urban',description:'',status:'active',badge:'',images:[],variants:['P','M','G','GG'].map(size=>({size,color:'Preto',stock:0,sku:''})),...product,expectedUpdatedAt:product?.updatedAt||null,expectedStock:product?.variants.map(v=>({id:v.id,stock:v.stock}))||[],price:product?String(product.price/100):'',cost:product?String(product.cost/100):'0',compareAt:product?String(product.compareAt/100):'0'}));
  const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const [library,setLibrary]=useState(false); const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  const updateVariant=(index,key,value)=>setForm(f=>({...f,variants:f.variants.map((v,i)=>i===index?{...v,[key]:value}:v)}));
  async function upload(files){setError('');if(form.images.length+files.length>5){setError('Use até 5 imagens por produto.');return;}setUploading(true);try{const media=await store.upload([...files]);setForm(f=>({...f,images:[...f.images,...media.map(m=>m.url)]}));}catch(e){setError(e.message);}finally{setUploading(false);}}
  return <Form label={product?.id?'Salvar alterações':'Cadastrar roupa'} busy={uploading} onSubmit={()=>onSave({...form,price:toCents(form.price),cost:toCents(form.cost),compareAt:toCents(form.compareAt||0),variants:form.variants.map(v=>({...v,stock:Number(v.stock)}))})}>
    <div className="ad-editor-grid"><div><h3 className="ad-form-title">Informações da roupa</h3><Field label="Nome da roupa *" value={form.name} onChange={e=>set('name',e.target.value)} required maxLength={140}/><div className="ad-form-row"><Field label="SKU / código *" value={form.sku} onChange={e=>set('sku',e.target.value)} required maxLength={60}/><Field label="Categoria *"><select value={form.category} onChange={e=>set('category',e.target.value)} required>{store.state.categories.map(c=><option key={c}>{c}</option>)}</select></Field></div><Field label="Descrição"><textarea rows="4" value={form.description} onChange={e=>set('description',e.target.value)} maxLength={3000}/></Field><div className="ad-form-row"><Field label="Coleção" value={form.collection} onChange={e=>set('collection',e.target.value)}/><Field label="Etiqueta na vitrine" value={form.badge} placeholder="NOVO DROP" onChange={e=>set('badge',e.target.value)} maxLength={25}/></div><h3 className="ad-form-title">Preço e publicação</h3><div className="ad-form-row three"><Field label="Preço de venda (R$) *" type="number" min="0.01" step="0.01" value={form.price} onChange={e=>set('price',e.target.value)} required/><Field label="Custo (R$)" type="number" min="0" step="0.01" value={form.cost} onChange={e=>set('cost',e.target.value)} required/><Field label="Preço anterior (R$)" type="number" min="0" step="0.01" value={form.compareAt} onChange={e=>set('compareAt',e.target.value)} hint="Zero para não mostrar."/></div><Field label="Status"><select value={form.status} onChange={e=>set('status',e.target.value)}><option value="active">Ativo — disponível na vitrine</option><option value="draft">Rascunho — oculto da vitrine</option><option value="archived">Arquivado</option></select></Field></div>
    <div><h3 className="ad-form-title">Fotos do produto <small>{form.images.length}/5</small></h3><div className="ad-image-editor">{form.images.map((url,i)=><div key={`${url.slice(0,100)}-${i}`}><img src={url} alt={`Foto ${i+1} da roupa`}/>{i===0&&<span>CAPA</span>}<button type="button" aria-label={`Remover foto ${i+1}`} onClick={()=>set('images',form.images.filter((_,j)=>j!==i))}><I name="close" size={14}/></button></div>)}</div><label className={`ad-dropzone ${uploading?'disabled':''}`}><I name="upload" size={26}/><strong>{uploading?'Enviando imagens…':'Clique para enviar suas fotos'}</strong><span>JPG, PNG ou WebP · até 5 MB cada</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple disabled={uploading} onChange={e=>{upload(e.target.files);e.target.value='';}}/></label><button type="button" className="ad-text-button" onClick={()=>setLibrary(!library)}>Escolher da biblioteca de imagens</button>{library&&<div className="ad-library-picker">{[...new Map([...store.state.media,...store.state.products.flatMap(p=>p.images.map(url=>({url,name:p.name})))].map(m=>[m.url,m])).values()].map((m,i)=><button type="button" key={i} disabled={form.images.includes(m.url)||form.images.length>=5} onClick={()=>set('images',[...form.images,m.url])}><img src={m.url} alt={m.name}/></button>)}{!store.state.media.length&&!store.state.products.length&&<p>Envie sua primeira imagem acima.</p>}</div>}{error&&<div className="ad-error" role="alert">{error}</div>}<div className="ad-tip"><I name="image"/><p>A primeira foto será a capa. As imagens são otimizadas antes do envio.</p></div></div></div>
    <div className="ad-variants-heading"><div><h3>Variações e estoque</h3><p>Uma linha para cada combinação de cor e tamanho.</p></div><Button type="button" kind="secondary" icon="plus" onClick={()=>set('variants',[...form.variants,{size:'M',color:'Preto',stock:0,sku:''}])}>Adicionar variação</Button></div><div className="ad-table-wrap"><table className="ad-table variant-table"><thead><tr><th>Tamanho *</th><th>Cor *</th><th>SKU da variação</th><th>Em estoque *</th><th/></tr></thead><tbody>{form.variants.map((v,i)=><tr key={v.id||i}><td><input aria-label={`Tamanho da variação ${i+1}`} value={v.size} onChange={e=>updateVariant(i,'size',e.target.value)} required maxLength={20}/></td><td><input aria-label={`Cor da variação ${i+1}`} value={v.color} onChange={e=>updateVariant(i,'color',e.target.value)} required maxLength={40}/></td><td><input aria-label={`SKU da variação ${i+1}`} value={v.sku} onChange={e=>updateVariant(i,'sku',e.target.value)} placeholder={`${form.sku}-${i+1}`}/></td><td><input aria-label={`Estoque da variação ${i+1}`} type="number" value={v.stock} min="0" max="100000" step="1" onChange={e=>updateVariant(i,'stock',e.target.value)} required/></td><td><button type="button" className="ad-icon" disabled={form.variants.length===1} aria-label={`Remover variação ${i+1}`} onClick={()=>set('variants',form.variants.filter((_,j)=>j!==i))}><I name="close" size={17}/></button></td></tr>)}</tbody></table></div>
  </Form>;
}
function CustomerForm({customer,onSave}) {const [f,set]=useState({name:'',email:'',phone:'',address:'',notes:'',...customer});const change=key=>e=>set({...f,[key]:e.target.value});return <Form onSubmit={()=>onSave(f)}><Field label="Nome *" value={f.name} onChange={change('name')} required maxLength={100}/><div className="ad-form-row"><Field label="E-mail" type="email" value={f.email} onChange={change('email')}/><Field label="Telefone de contato" value={f.phone} onChange={change('phone')} hint="Contato interno da loja. O número do checkout está indicado abaixo."/></div><Field label="Endereço"><textarea value={f.address} onChange={change('address')} rows="3"/></Field><Field label="Observações"><textarea value={f.notes} onChange={change('notes')} rows="3"/></Field></Form>;}
function CouponForm({coupon,onSave}) {const [f,set]=useState({code:'',type:'percent',limit:0,expires:'',active:true,...coupon,value:coupon?String(coupon.type==='fixed'?coupon.value/100:coupon.value):'10',minimum:coupon?String(coupon.minimum/100):'0'});const change=key=>e=>set({...f,[key]:e.target.value});return <Form onSubmit={()=>onSave({...f,value:f.type==='fixed'?toCents(f.value):Number(f.value),minimum:toCents(f.minimum),limit:Number(f.limit)})}><Field label="Código *" value={f.code} onChange={change('code')} placeholder="GRIFF10" required/><div className="ad-form-row"><Field label="Tipo"><select value={f.type} onChange={change('type')}><option value="percent">Percentual (%)</option><option value="fixed">Valor fixo (R$)</option></select></Field><Field label={f.type==='percent'?'Desconto (%)':'Desconto (R$)'} type="number" min="0.01" max={f.type==='percent'?100:undefined} step={f.type==='percent'?'1':'.01'} value={f.value} onChange={change('value')} required/></div><div className="ad-form-row"><Field label="Compra mínima (R$)" type="number" min="0" step=".01" value={f.minimum} onChange={change('minimum')}/><Field label="Máximo de usos" type="number" min="0" step="1" value={f.limit} onChange={change('limit')} hint="Zero significa sem limite."/></div><Field label="Data de validade" type="date" value={f.expires} onChange={change('expires')}/><label className="ad-checkbox"><input type="checkbox" checked={f.active} onChange={e=>set({...f,active:e.target.checked})}/> Cupom ativo</label></Form>;}
function ExpenseForm({expense,onSave}) {const [f,set]=useState({description:'',category:'Operacional',date:new Date().toISOString().slice(0,10),...expense,amount:expense?String(expense.amount/100):''});const change=k=>e=>set({...f,[k]:e.target.value});return <Form onSubmit={()=>onSave({...f,amount:toCents(f.amount)})}><Field label="Descrição *" value={f.description} onChange={change('description')} required/><div className="ad-form-row"><Field label="Categoria"><select value={f.category} onChange={change('category')}>{['Operacional','Embalagens','Marketing','Aluguel','Frete','Outros'].map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Valor (R$) *" type="number" min=".01" step=".01" value={f.amount} onChange={change('amount')} required/></div><Field label="Data *" type="date" value={f.date} onChange={change('date')} required/></Form>;}
function StockForm({product,variant,onSave}) {const [direction,setDirection]=useState('in');const [qty,setQty]=useState(1);const [reason,setReason]=useState('');return <Form onSubmit={()=>onSave({productId:product.id,variantId:variant.id,delta:Number(qty)*(direction==='in'?1:-1),reason})}><div className="ad-product-mini"><img src={productImage(product)} alt=""/><div><strong>{product.name}</strong><small>{variant.color} / {variant.size} · {variant.stock} unidades disponíveis</small></div></div><div className="ad-form-row"><Field label="Movimentação"><select value={direction} onChange={e=>setDirection(e.target.value)}><option value="in">Entrada de mercadoria</option><option value="out">Saída / ajuste</option></select></Field><Field label="Quantidade *" type="number" min="1" max={direction==='out'?variant.stock:100000} step="1" value={qty} onChange={e=>setQty(e.target.value)} required/></div><Field label="Motivo *" value={reason} onChange={e=>setReason(e.target.value)} placeholder="Ex.: reposição, avaria, contagem física" required/></Form>;}
function CategoryForm({old,onSave}) {const [name,setName]=useState(old||'');return <Form onSubmit={()=>onSave({old,name})}><Field label="Nome da categoria *" value={name} onChange={e=>setName(e.target.value)} required maxLength={60}/></Form>;}

function OrderForm({onSave}) {const {state,demo}=useStore();const available=state.products.filter(p=>p.status==='active');const [f,set]=useState({customerId:'',name:demo?'Cliente de demonstração':'',email:'',phone:'',address:'',method:'pix',paid:false,shipping:'0',coupon:'',notes:'',channel:'manual'});const [lines,setLines]=useState([]);const [p,setP]=useState('');const [v,setV]=useState('');const [qty,setQty]=useState(1);const [error,setError]=useState('');const change=k=>e=>set({...f,[k]:e.target.value});const chosen=available.find(x=>x.id===p);const subtotal=lines.reduce((n,l)=>n+state.products.find(p=>p.id===l.productId).price*l.qty,0);return <Form label="Criar pedido e reservar estoque" onSubmit={()=>onSave({items:lines,customerId:f.customerId||undefined,customer:{name:f.name,email:f.email,phone:f.phone,address:f.address},method:f.method,paid:f.paid,saveCustomer:!f.customerId,shipping:toCents(f.shipping),coupon:f.coupon,notes:f.notes,channel:f.channel})}><div className="ad-editor-grid"><div><h3 className="ad-form-title">Cliente e entrega</h3><Field label="Cliente cadastrado"><select value={f.customerId} onChange={change('customerId')}><option value="">Informar cliente neste pedido</option>{state.customers.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field>{!f.customerId&&<><Field label="Nome do cliente *" value={f.name} onChange={change('name')} required/><div className="ad-form-row"><Field label="E-mail" type="email" value={f.email} onChange={change('email')}/><Field label="Telefone" value={f.phone} onChange={change('phone')}/></div><Field label="Endereço / retirada"><textarea value={f.address} onChange={change('address')} rows="2"/></Field></>}<Field label="Observações"><textarea value={f.notes} onChange={change('notes')} rows="2"/></Field></div><div><h3 className="ad-form-title">Itens do pedido</h3><Field label="Produto"><select value={p} onChange={e=>{setP(e.target.value);setV('');}}><option value="">Selecione uma roupa</option>{available.map(p=><option key={p.id} value={p.id}>{p.name} · {money(p.price)}</option>)}</select></Field><div className="ad-form-row"><Field label="Variação"><select value={v} onChange={e=>setV(e.target.value)}><option value="">Tamanho e cor</option>{chosen?.variants.map(v=><option key={v.id} value={v.id} disabled={!v.stock}>{v.color}/{v.size} · {v.stock} un.</option>)}</select></Field><Field label="Quantidade" type="number" min="1" step="1" value={qty} onChange={e=>setQty(e.target.value)}/></div><Button type="button" kind="secondary" icon="plus" onClick={()=>{if(!p||!v||Number(qty)<1){setError('Selecione produto, variação e quantidade.');return;}setLines([...lines,{productId:p,variantId:v,qty:Number(qty)}]);setP('');setV('');setQty(1);setError('');}}>Adicionar item</Button>{error&&<p className="ad-error">{error}</p>}<div className="ad-order-lines">{lines.map((l,i)=>{const product=state.products.find(p=>p.id===l.productId);const variant=product.variants.find(v=>v.id===l.variantId);return <div key={i}><span><b>{l.qty}× {product.name}</b><small>{variant.color}/{variant.size}</small></span><strong>{money(product.price*l.qty)}</strong><button type="button" className="ad-icon" onClick={()=>setLines(lines.filter((_,j)=>j!==i))} aria-label={`Remover item ${i+1}`}><I name="close" size={16}/></button></div>;})}</div><div className="ad-order-subtotal"><span>Subtotal dos itens</span><strong>{money(subtotal)}</strong></div></div></div><div className="ad-form-row three"><Field label="Frete (R$)" type="number" min="0" step=".01" value={f.shipping} onChange={change('shipping')}/><Field label="Cupom" value={f.coupon} onChange={change('coupon')} placeholder="Opcional"/><Field label="Forma de pagamento"><select value={f.method} onChange={change('method')}>{Object.entries(paymentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field></div><label className="ad-checkbox"><input type="checkbox" checked={f.paid} onChange={e=>set({...f,paid:e.target.checked})}/> Confirmo que o pagamento já foi recebido fora do sistema.</label><div className="ad-tip"><I name="bag"/><p>O estoque será reservado ao criar o pedido. O painel registra pagamentos recebidos; não realiza cobranças nem estornos bancários.</p></div></Form>;}
function OrderDetail({order,onUpdate,onRefund}) {const [error,setError]=useState('');const [tracking,setTracking]=useState(order.tracking);const [notes,setNotes]=useState(order.notes);const [refund,setRefund]=useState(false);const [reason,setReason]=useState('');const [restock,setRestock]=useState(true);const {busy}=useStore();const action=async data=>{setError('');try{await onUpdate({id:order.id,...data});}catch(e){setError(e.message);}};const next={pending:[['preparing','Preparar pedido'],['canceled','Cancelar pedido']],preparing:[['shipped','Marcar como enviado'],['delivered','Registrar entrega/retirada'],['canceled','Cancelar pedido']],shipped:[['delivered','Marcar como entregue']],delivered:[],canceled:[],returned:[]};return <><div className="ad-order-summary"><div><Badge value={order.status}/><Badge value={order.payment}/></div><strong>{money(order.total)}</strong></div><div className="ad-order-customer"><h3>{order.customer.name}</h3><p>{[order.customer.email,order.customer.phone].filter(Boolean).join(' · ')||'Contato não informado'}</p><p>{order.customer.address||'Endereço não informado'}</p></div><div className="ad-order-lines">{order.items.map((i,index)=><div key={index}><span><b>{i.qty}× {i.name}</b><small>{i.color} / {i.size} · {i.sku}</small></span><strong>{money(i.qty*i.unitPrice)}</strong></div>)}</div><dl className="ad-totals"><div><dt>Subtotal</dt><dd>{money(order.subtotal)}</dd></div><div><dt>Desconto {order.coupon&&`(${order.coupon})`}</dt><dd>− {money(order.discount)}</dd></div><div><dt>Frete</dt><dd>{money(order.shipping)}</dd></div><div><dt>Pagamento</dt><dd>{paymentLabels[order.method]}</dd></div></dl><div className="ad-form-row"><Field label="Código de rastreio" value={tracking} onChange={e=>setTracking(e.target.value)}/><Field label="Observações" value={notes} onChange={e=>setNotes(e.target.value)}/></div><div className="ad-detail-actions"><Button kind="secondary" disabled={busy} onClick={()=>action({tracking,notes})}>Salvar observações</Button>{order.payment==='pending'&&!['canceled','returned'].includes(order.status)&&<Button disabled={busy} onClick={()=>action({markPaid:true})}>Registrar pagamento recebido</Button>}{next[order.status].filter(([s])=>s!=='canceled'||order.payment!=='paid').map(([status,label])=><Button key={status} kind={status==='canceled'?'danger':'secondary'} disabled={busy} onClick={()=>action({status})}>{label}</Button>)}{order.payment==='paid'&&<Button kind="danger" onClick={()=>setRefund(!refund)}>Registrar devolução / estorno</Button>}</div>{refund&&<div className="ad-refund"><h3>Registrar estorno realizado fora do sistema</h3><Field label="Motivo *" value={reason} onChange={e=>setReason(e.target.value)}/><label className="ad-checkbox"><input type="checkbox" checked={restock} onChange={e=>setRestock(e.target.checked)}/> Devolver as peças ao estoque</label><Button kind="danger" disabled={busy} onClick={async()=>{try{await onRefund({id:order.id,reason,restock});setRefund(false);}catch(e){setError(e.message);}}}>Confirmar registro de estorno</Button></div>}{error&&<p className="ad-error" role="alert">{error}</p>}<h3 className="ad-form-title">Histórico do pedido</h3><div className="ad-timeline">{order.events.map((e,i)=><div key={i}><span/><p>{e.text}<small>{new Date(e.at).toLocaleString('pt-BR')} · {e.actor}</small></p></div>)}</div></>;}

export default function Admin() {
 const store=useStore();const {state,demo,busy}=store;const [tab,setTab]=useState('overview');const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');const [page,setPage]=useState(1);const [days,setDays]=useState(30);const [modal,setModal]=useState(null);const [toast,setToast]=useState('');const [mobile,setMobile]=useState(false);const [globalError,setGlobalError]=useState('');const [uploading,setUploading]=useState(false);const timer=useRef(null);
 useEffect(()=>()=>clearTimeout(timer.current),[]);useEffect(()=>{setPage(1);},[query,filter,tab]);const go=next=>{setTab(next);setQuery('');setFilter('all');setPage(1);setMobile(false);};
 function notify(message){setToast(message);clearTimeout(timer.current);timer.current=setTimeout(()=>setToast(''),4000);}
 async function save(type,data,message='Dados salvos com sucesso.',keep=false){const result=await store.run(type,data);notify(message);if(!keep)setModal(null);return result;}
 async function action(type,data,message){try{setGlobalError('');await save(type,data,message);}catch(e){setGlobalError(e.message);}}
 if(store.loading)return <div className="ad-loading"><div className="ad-spinner"/><strong>Preparando o painel da Griff…</strong></div>;
 if(store.error&&!state)return <div className="ad-loading"><I name="alert" size={36}/><h2>Não foi possível abrir o painel</h2><p>{store.error}</p><Button onClick={store.refresh}>Tentar novamente</Button></div>;
 const metrics=report(state,days);const matching=text=>text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));
 const products=state.products.filter(p=>matching(`${p.name} ${p.sku} ${p.category}`)&&(filter==='all'||p.status===filter));const orders=state.orders.filter(o=>matching(`${o.number} ${o.customer.name} ${o.customer.email}`)&&(filter==='all'||o.status===filter||o.payment===filter));const inventory=state.products.filter(p=>p.status!=='archived').flatMap(p=>p.variants.map(v=>({...v,product:p}))).filter(v=>matching(`${v.product.name} ${v.sku} ${v.size} ${v.color}`)&&(filter!=='low'||v.stock<=state.settings.lowStock));const customers=state.customers.filter(c=>matching(`${c.name} ${c.email} ${c.phone}`));const shown=list=>list.slice((page-1)*10,page*10);const activeOrder=modal?.orderId?state.orders.find(o=>o.id===modal.orderId):null;
 const exportOrders=()=>download('griff-pedidos.csv',csv([['Pedido','Data','Cliente','Status','Pagamento','Subtotal (R$)','Desconto (R$)','Frete (R$)','Total (R$)'],...orders.map(o=>[o.number,o.createdAt,o.customer.name,statusLabels[o.status],statusLabels[o.payment],(o.subtotal/100).toFixed(2),(o.discount/100).toFixed(2),(o.shipping/100).toFixed(2),(o.total/100).toFixed(2)])]));
 const orderTable=(rows,compact=false)=><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Pedido</th><th>Cliente</th>{!compact&&<th>Data</th>}<th>Pagamento</th><th>Status</th><th className="right">Total</th><th/></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><button className="ad-order-number" onClick={()=>setModal({type:'order',orderId:o.id})}>{o.number}</button></td><td><strong className="ad-cell-name">{o.customer.name}</strong><small>{o.items.reduce((n,i)=>n+i.qty,0)} peças</small></td>{!compact&&<td>{dateLabel(o.createdAt)}</td>}<td><Badge value={o.payment}/></td><td><Badge value={o.status}/></td><td className="right"><b>{money(o.total)}</b></td><td><button className="ad-icon" aria-label={`Abrir pedido ${o.number}`} onClick={()=>setModal({type:'order',orderId:o.id})}><I name="arrow" size={17}/></button></td></tr>)}</tbody></table>{!rows.length&&<Empty icon="bag" title="Nenhum pedido encontrado" text="Cadastre uma venda para começar a acompanhar seus pedidos."/>}</div>;
 const Heading=({title,text,children})=><div className="ad-page-heading"><div><span className="ad-overline">GRIFF CASUAL / ADMINISTRAÇÃO</span><h1>{title}</h1><p>{text}</p></div><div className="ad-heading-actions">{children}</div></div>;
 const period=<select className="ad-period" aria-label="Período do relatório" value={days} onChange={e=>setDays(Number(e.target.value))}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option></select>;
 return <div className="admin-app"><aside className={`ad-sidebar ${mobile?'open':''}`}><a className="ad-logo" href="#/admin"><img src="images/griff-original.jpg" alt=""/><span>GRIFF <small>CASUAL / ADMIN</small></span></a><div className="ad-sidebar-section">WORKSPACE</div><nav aria-label="Menu administrativo">{menu.map(([id,label,icon])=><button className={tab===id?'active':''} onClick={()=>go(id)} key={id}><I name={icon} size={19}/><span>{label}</span>{id==='orders'&&metrics.pending.length>0&&<b>{metrics.pending.length}</b>}</button>)}</nav><div className="ad-sidebar-bottom"><div className="ad-store-status"><span/> {demo?'Ambiente de demonstração':'Painel conectado'}</div><a href="#inicio"><I name="arrow" size={17}/> Ir para a vitrine</a><small>Griff Casual · Gestão da loja</small></div></aside>{mobile&&<button className="ad-menu-shade" aria-label="Fechar menu" onClick={()=>setMobile(false)}/>}
 <div className="ad-workspace"><header className="ad-topbar"><div><button className="ad-icon ad-mobile-menu" aria-label="Abrir menu administrativo" onClick={()=>setMobile(!mobile)}><I name="menu"/></button><span className="ad-breadcrumb">Loja <span>/</span> <strong>{menu.find(m=>m[0]===tab)?.[1]}</strong></span></div><div><span className={`ad-mode ${demo?'demo':''}`}><i/>{demo?'DEMONSTRAÇÃO':'CONEXÃO SEGURA'}</span><a className="ad-preview" href="#inicio">Ver loja <I name="arrow" size={14}/></a><button className="ad-icon" aria-label="Atualizar dados" title="Atualizar dados" disabled={busy} onClick={() => store.refresh()}><I name="check" size={17}/></button><span className="ad-avatar">{store.user?.email?.slice(0,1).toUpperCase()||'G'}</span></div></header>
 {demo&&<div className="ad-demo-banner"><I name="alert" size={15}/><span>Dados de exemplo, salvos apenas neste navegador. Não cadastre informações pessoais reais.</span><a href="#/admin/settings" onClick={()=>go('settings')}>Sobre o acesso <I name="arrow" size={13}/></a></div>}
 <main className="ad-main">{globalError&&<div className="ad-error" role="alert">{globalError}<button aria-label="Fechar aviso" onClick={()=>setGlobalError('')}><I name="close" size={16}/></button></div>}
 {tab==='overview'&&<><Heading title="Seu corre, sob controle." text={`Bem-vindo à gestão da ${state.settings.name}. Tudo o que importa, em um só lugar.`}>{period}<Button icon="plus" onClick={()=>setModal({type:'new-order'})}>Novo pedido</Button></Heading><div className="ad-metrics">{[['Receita recebida',money(metrics.revenue),'wallet','Somente pedidos pagos'],['Pedidos pagos',metrics.paid.length,'bag',`${metrics.pending.length} pedidos em andamento`],['Ticket médio',money(metrics.average),'chart','Por pedido pago no período'],['Peças em estoque',metrics.totalStock,'box',`${metrics.low.length} variações com estoque baixo`]].map(([label,value,icon,note],i)=><div className={`ad-metric ${i===0?'featured':''}`} key={label}><div><span>{label}</span><I name={icon} size={19}/></div><strong>{value}</strong><small>{i===3&&metrics.low.length>0&&<i/>}{note}</small></div>)}</div><div className="ad-dashboard-grid"><section className="ad-card"><div className="ad-card-heading"><div><h2>Receita no período</h2><p>Acompanhe os pagamentos registrados.</p></div><span className="ad-chart-legend"><i/> Recebido</span></div><RevenueChart state={state} days={days}/><div className="ad-chart-summary"><span><i/>Total recebido <strong>{money(metrics.revenue)}</strong></span><button className="ad-text-button" onClick={()=>go('reports')}>Ver relatório <I name="arrow" size={15}/></button></div></section><section className="ad-card ad-stock-alert"><div className="ad-card-heading"><div><h2>Atenção ao estoque</h2><p>Reposição na hora certa.</p></div><span className="ad-alert-count">{metrics.low.length}</span></div>{metrics.low.length?metrics.low.slice(0,4).map(v=><button className="ad-low-item" key={v.id} onClick={()=>setModal({type:'stock',product:v.product,variant:v})}><img src={productImage(v.product)} alt=""/><span><b>{v.product.name}</b><small>{v.color} / {v.size}</small></span><strong className={v.stock===0?'zero':''}>{v.stock} un.</strong></button>):<Empty icon="check" title="Estoque em dia" text="Nenhuma variação abaixo do limite de alerta."/>}<button className="ad-text-button" onClick={()=>{go('inventory');setFilter('low');}}>Gerenciar estoque <I name="arrow" size={15}/></button></section></div><section className="ad-card"><div className="ad-card-heading"><div><h2>Pedidos recentes</h2><p>Do primeiro contato até a entrega.</p></div><button className="ad-text-button" onClick={()=>go('orders')}>Todos os pedidos <I name="arrow" size={15}/></button></div>{orderTable(state.orders.slice(0,5),true)}</section><div className="ad-bottom-grid"><section className="ad-card"><div className="ad-card-heading"><h2>Atividade da loja</h2></div><div className="ad-activity">{state.activity.slice(0,5).map(a=><div key={a.id}><span><I name="check" size={13}/></span><p>{a.description}<small>{dateLabel(a.at)} · {a.actor}</small></p></div>)}{!state.activity.length&&<p>Seu histórico de alterações aparecerá aqui.</p>}</div></section><section className="ad-brand-card"><span>GRIFF CASUAL / GESTÃO</span><h2>MAIS ORGANIZAÇÃO.<br/><em>MAIS ATITUDE.</em></h2><p>Cadastre seu próximo drop e deixe o estoque pronto para o corre.</p><Button icon="plus" onClick={()=>setModal({type:'product'})}>Cadastrar roupa</Button></section></div></>}
 {tab==='products'&&<><Heading title="Produtos" text="Organize suas roupas, variações, preços e imagens."><Button kind="secondary" onClick={()=>setModal({type:'categories'})}>Categorias</Button><Button icon="plus" onClick={()=>setModal({type:'product'})}>Cadastrar roupa</Button></Heading><section className="ad-card"><Filter query={query} setQuery={setQuery} placeholder="Buscar por nome, SKU ou categoria"><select aria-label="Filtrar status do produto" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todos os status</option><option value="active">Ativos</option><option value="draft">Rascunhos</option><option value="archived">Arquivados</option></select></Filter><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead><tbody>{shown(products).map(p=><tr key={p.id}><td><button className="ad-product-cell" onClick={()=>setModal({type:'product',product:p})}><img src={productImage(p)} alt=""/><span><b>{p.name}</b><small>{p.sku}</small></span></button></td><td>{p.category}</td><td><b>{money(p.price)}</b><small>Custo {money(p.cost)}</small></td><td>{p.variants.reduce((n,v)=>n+v.stock,0)} un.<small>{p.variants.length} variações</small></td><td><Badge value={p.status}/></td><td><div className="ad-row-actions"><button className="ad-text-button" onClick={()=>setModal({type:'product',product:p})}>Editar</button><button className="ad-text-button" aria-label={`Duplicar ${p.name}`} onClick={()=>setModal({type:'product',product:{...structuredClone(p),id:undefined,name:`${p.name} — cópia`,sku:`${p.sku}-COPIA`,status:'draft',variants:p.variants.map(v=>({...v,id:undefined,sku:`${v.sku}-COPIA`,stock:0}))}})}>Duplicar</button>{p.status!=='archived'&&<button className="ad-text-button danger-text" onClick={()=>setModal({type:'confirm',title:'Arquivar roupa?',text:`${p.name} sairá da vitrine. O histórico de vendas será preservado.`,action:()=>save('products.archive',{id:p.id},'Roupa arquivada.')})}>Arquivar</button>}</div></td></tr>)}</tbody></table>{!products.length&&<Empty icon="shirt" title="Seu próximo drop começa aqui" text="Cadastre suas roupas ou importe o catálogo ilustrativo para experimentar."><Button icon="plus" onClick={()=>setModal({type:'product'})}>Cadastrar roupa</Button>{!state.products.length&&<Button kind="secondary" disabled={busy} onClick={()=>action('catalog.seed',{},'Catálogo ilustrativo importado.')}>Importar catálogo de exemplo</Button>}</Empty>}</div><Pager page={page} setPage={setPage} total={products.length}/></section></>}
 {tab==='inventory'&&<><Heading title="Estoque" text="Controle entradas e saídas por tamanho e cor."><Button kind="secondary" icon="download" onClick={()=>download('griff-estoque.csv',csv([['Produto','SKU','Cor','Tamanho','Disponível'],...inventory.map(v=>[v.product.name,v.sku,v.color,v.size,v.stock])]))}>Exportar estoque</Button></Heading><div className="ad-inline-stats"><span>Peças disponíveis <b>{metrics.totalStock}</b></span><span>Variações com alerta <b>{metrics.low.length}</b></span><span>Limite do alerta <b>{state.settings.lowStock} un.</b></span></div><section className="ad-card"><Filter query={query} setQuery={setQuery} placeholder="Buscar produto, SKU, tamanho ou cor"><select aria-label="Filtrar estoque" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todo o estoque</option><option value="low">Estoque baixo / zerado</option></select></Filter><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Roupa</th><th>SKU</th><th>Cor / tamanho</th><th>Disponível</th><th/></tr></thead><tbody>{shown(inventory).map(v=><tr key={v.id}><td><strong>{v.product.name}</strong></td><td>{v.sku}</td><td>{v.color} / {v.size}</td><td><span className={`ad-stock-value ${v.stock<=state.settings.lowStock?'low':''}`}>{v.stock} un.</span></td><td><Button kind="secondary" icon="plus" onClick={()=>setModal({type:'stock',product:v.product,variant:v})}>Movimentar</Button></td></tr>)}</tbody></table>{!inventory.length&&<Empty title="Nenhuma variação encontrada"/>}</div><Pager page={page} setPage={setPage} total={inventory.length}/></section><section className="ad-card"><div className="ad-card-heading"><div><h2>Últimas movimentações</h2><p>Entradas, reservas e devoluções registradas.</p></div></div><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Data</th><th>Produto / variação</th><th>Motivo</th><th>Movimento</th><th>Saldo após</th></tr></thead><tbody>{state.movements.slice(0,15).map(m=><tr key={m.id}><td>{dateLabel(m.at)}</td><td>{m.productName}<small>{m.variant}</small></td><td>{m.reason}</td><td className={m.delta>0?'positive':'negative'}>{m.delta>0?'+':''}{m.delta}</td><td>{m.after}</td></tr>)}</tbody></table>{!state.movements.length&&<Empty title="Sem movimentações ainda"/>}</div></section></>}
 {tab==='orders'&&<><Heading title="Pedidos e vendas" text="Acompanhe pagamentos, preparação, entrega e devoluções."><Button kind="secondary" icon="download" onClick={exportOrders}>Exportar CSV</Button><Button icon="plus" onClick={()=>setModal({type:'new-order'})}>Novo pedido</Button></Heading><div className="ad-inline-stats"><span>Em andamento <b>{metrics.pending.length}</b></span><span>Pagos no período <b>{metrics.paid.length}</b></span><span>Receita no período <b>{money(metrics.revenue)}</b></span></div><section className="ad-card"><Filter query={query} setQuery={setQuery} placeholder="Buscar pedido, cliente ou e-mail"><select aria-label="Filtrar pedidos" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todos os pedidos</option>{['pending','preparing','shipped','delivered','canceled','returned','paid','refunded'].map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select></Filter>{orderTable(shown(orders))}<Pager page={page} setPage={setPage} total={orders.length}/></section></>}
 {tab==='customers'&&<><Heading title="Clientes" text="Mantenha os contatos e consulte o histórico de compras."><Button kind="secondary" icon="download" onClick={()=>download('griff-clientes.csv',csv([['Nome','E-mail','Telefone','Endereço'],...customers.map(c=>[c.name,c.email,c.phone,c.address])]))}>Exportar CSV</Button><Button icon="plus" onClick={()=>setModal({type:'customer'})}>Cadastrar cliente</Button></Heading><section className="ad-card"><Filter query={query} setQuery={setQuery} placeholder="Buscar nome, telefone ou e-mail"/><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Cliente</th><th>Contato</th><th>Pedidos</th><th>Total pago</th><th/></tr></thead><tbody>{shown(customers).map(c=>{const history=state.orders.filter(o=>o.customer.id===c.id);return <tr key={c.id}><td><strong>{c.name}</strong><small>Desde {dateLabel(c.createdAt)}</small></td><td>{c.email||'Sem e-mail'}<small>{c.phone||'Sem telefone'}</small></td><td>{history.length}</td><td>{money(history.filter(o=>o.payment==='paid').reduce((n,o)=>n+o.total,0))}</td><td><button className="ad-text-button" onClick={()=>setModal({type:'customer',customer:c})}>Editar cadastro</button></td></tr>;})}</tbody></table>{!customers.length&&<Empty icon="users" title="Seus clientes, mais perto" text="Cadastre contatos para preencher novos pedidos com mais agilidade."/>}</div><Pager page={page} setPage={setPage} total={customers.length}/></section></>}
 {tab==='coupons'&&<><Heading title="Cupons" text="Crie incentivos com limites e validade definidos."><Button icon="plus" onClick={()=>setModal({type:'coupon'})}>Criar cupom</Button></Heading><div className="ad-coupon-grid">{state.coupons.map(c=><section className="ad-card ad-coupon" key={c.id}><div><I name="tag"/><Badge value={c.active?'active':'draft'}/></div><strong>{c.code}</strong><h2>{c.type==='percent'?`${c.value}% OFF`:money(c.value)+' OFF'}</h2><p>Compra mínima: {money(c.minimum)}</p><p>Validade: {c.expires?dateLabel(c.expires):'Sem data definida'}</p><p>Usos: {state.orders.filter(o=>o.coupon===c.code&&!['canceled','returned'].includes(o.status)).length}{c.limit?` de ${c.limit}`:' · sem limite'}</p><Button kind="secondary" icon="edit" onClick={()=>setModal({type:'coupon',coupon:c})}>Editar cupom</Button></section>)}</div>{!state.coupons.length&&<section className="ad-card"><Empty icon="tag" title="Seu próximo incentivo" text="Crie um cupom percentual ou de valor fixo para seus pedidos."/></section>}</>}
 {tab==='finance'&&<><Heading title="Financeiro" text="Registre despesas e acompanhe o resultado operacional.">{period}<Button icon="plus" onClick={()=>setModal({type:'expense'})}>Registrar despesa</Button></Heading><div className="ad-metrics"><Metric label="Receita recebida" value={money(metrics.revenue)} icon="wallet"/><Metric label="Custo das peças vendidas" value={money(metrics.cost)} icon="shirt"/><Metric label="Despesas no período" value={money(metrics.expenses)} icon="bag"/><Metric label="Resultado estimado" value={money(metrics.profit)} icon="chart" note="Receita − frete − custos − despesas"/></div><div className="ad-tip"><I name="wallet"/><p>Os valores são calculados a partir dos registros manuais. Frete é excluído do resultado; taxas bancárias e impostos devem ser cadastrados como despesas. Este painel não faz conciliação bancária nem contabilidade fiscal.</p></div><section className="ad-card"><div className="ad-card-heading"><div><h2>Despesas registradas</h2><p>Lista completa de lançamentos.</p></div><button className="ad-text-button" onClick={()=>download('griff-despesas.csv',csv([['Data','Descrição','Categoria','Valor (R$)'],...state.expenses.map(e=>[e.date,e.description,e.category,(e.amount/100).toFixed(2)])]))}>Exportar CSV <I name="download" size={15}/></button></div><div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th/></tr></thead><tbody>{state.expenses.map(e=><tr key={e.id}><td>{dateLabel(e.date)}</td><td>{e.description}</td><td>{e.category}</td><td><b>{money(e.amount)}</b></td><td><div className="ad-row-actions"><button className="ad-text-button" onClick={()=>setModal({type:'expense',expense:e})}>Editar</button><button className="ad-text-button danger-text" onClick={()=>setModal({type:'confirm',title:'Remover despesa?',text:e.description,action:()=>save('expenses.delete',{id:e.id},'Despesa removida.')})}>Remover</button></div></td></tr>)}</tbody></table>{!state.expenses.length&&<Empty icon="wallet" title="Nenhuma despesa cadastrada"/>}</div></section></>}
 {tab==='reports'&&<><Heading title="Relatórios" text="Transforme os registros da loja em decisões para o próximo drop.">{period}<Button kind="secondary" icon="download" onClick={()=>download('griff-resumo.csv',csv([['Indicador','Valor'],['Período (dias)',days],['Receita paga (R$)',(metrics.revenue/100).toFixed(2)],['Pedidos pagos',metrics.paid.length],['Ticket médio (R$)',(metrics.average/100).toFixed(2)],['Custo (R$)',(metrics.cost/100).toFixed(2)],['Despesas (R$)',(metrics.expenses/100).toFixed(2)],['Resultado estimado (R$)',(metrics.profit/100).toFixed(2)]]))}>Exportar resumo</Button></Heading><div className="ad-metrics"><Metric label="Receita recebida" value={money(metrics.revenue)} icon="wallet"/><Metric label="Pedidos pagos" value={metrics.paid.length} icon="bag"/><Metric label="Ticket médio" value={money(metrics.average)} icon="chart"/><Metric label="Resultado estimado" value={money(metrics.profit)} icon="chart"/></div><section className="ad-card"><div className="ad-card-heading"><h2>Evolução da receita</h2></div><RevenueChart state={state} days={days}/></section><section className="ad-card"><div className="ad-card-heading"><div><h2>Peças mais vendidas</h2><p>Considera apenas pedidos pagos no período selecionado.</p></div></div><TopProducts orders={metrics.paid}/></section></>}
 {tab==='media'&&<><Heading title="Biblioteca de imagens" text="Envie fotos e reutilize-as no cadastro das roupas."><label className={`ad-button primary ${uploading?'disabled':''}`}><I name="upload" size={17}/>{uploading?'Enviando…':'Enviar imagens'}<input className="ad-file-hidden" type="file" accept="image/jpeg,image/png,image/webp" multiple disabled={uploading} onChange={async e=>{const files=[...e.target.files];e.target.value='';if(files.length>5){setGlobalError('Envie até 5 imagens por vez.');return;}setUploading(true);try{await store.upload(files);notify('Imagens enviadas à biblioteca.');}catch(e){setGlobalError(e.message);}finally{setUploading(false);}}}/></label></Heading><div className="ad-media-grid">{state.media.map(m=><div className="ad-card ad-media-card" key={m.id}><img src={m.url} alt={m.name}/><div><strong>{m.name}</strong><small>{dateLabel(m.createdAt)}</small></div></div>)}</div>{!state.media.length&&<section className="ad-card"><Empty icon="image" title="Suas fotos merecem destaque" text="Envie JPG, PNG ou WebP de até 5 MB. As fotos do catálogo importado continuam nos próprios produtos."/></section>}</>}
 {tab==='settings'&&<><Heading title="Configurações" text="A identidade e os detalhes da sua loja, do seu jeito."/><div className="ad-settings-grid"><section className="ad-card ad-settings-form"><h2>Dados da loja</h2><SettingsForm settings={state.settings} onSave={data=>save('settings.save',data,'Configurações atualizadas.',true)}/></section><div><section className="ad-card ad-access-card"><I name="settings" size={26}/><h2>Acesso e armazenamento</h2><p>{demo?'Esta é uma demonstração local. Os dados e imagens são salvos somente neste navegador.':'Os dados são salvos no banco e as imagens no armazenamento da loja. O acesso exige uma conta de administrador autorizada.'}</p>{store.user?.email&&<strong>{store.user.email}</strong>}{!demo&&store.signOut&&<Button kind="secondary" icon="logout" onClick={store.signOut}>Sair do painel</Button>}</section><section className="ad-card ad-access-card"><I name="download" size={25}/><h2>Exportação dos dados</h2><p>Baixe um arquivo JSON com os registros da loja. As referências das imagens são incluídas; os arquivos de imagem precisam de cópia separada.</p><Button kind="secondary" icon="download" onClick={()=>download(`griff-dados-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({exportedAt:new Date().toISOString(),schema:1,data:state},null,2),'application/json')}>Exportar dados JSON</Button></section></div></div></>}
 <footer className="ad-footer"><span>GRIFF CASUAL · SEU NEGÓCIO, NO SEU RITMO.</span><span>{demo?'Demonstração · sem vendas reais':`Dados sincronizados · versão ${store.version}`}</span></footer></main></div>
 {toast&&<div className="ad-toast" role="status"><I name="check" size={18}/>{toast}</div>}
 {modal&&<Modal key={modal.type+(modal.product?.id||modal.orderId||'')} title={modal.type==='product'?(modal.product?.id?'Editar roupa':'Cadastrar roupa'):modal.type==='new-order'?'Novo pedido':modal.type==='order'?activeOrder?.number:modal.type==='customer'?'Cadastro de cliente':modal.type==='coupon'?'Configurar cupom':modal.type==='expense'?'Registrar despesa':modal.type==='stock'?'Movimentar estoque':modal.type==='category'?'Categoria':modal.type==='categories'?'Categorias da loja':modal.title||'Confirmar operação'} wide={['product','new-order'].includes(modal.type)} onClose={()=>setModal(null)}>
 {modal.type==='product'&&<ProductForm product={modal.product} onSave={data=>save('products.save',data,'Roupa salva no catálogo.')}/>}{modal.type==='new-order'&&<OrderForm onSave={data=>save('orders.create',data,'Pedido criado e estoque reservado.')}/>}{modal.type==='order'&&activeOrder&&<OrderDetail order={activeOrder} onUpdate={data=>save('orders.update',data,'Pedido atualizado.',true)} onRefund={data=>save('orders.refund',data,'Registro de estorno salvo.',true)}/>}{modal.type==='customer'&&<CustomerForm customer={modal.customer} onSave={data=>save('customers.save',data,'Cliente salvo.')}/>}{modal.type==='coupon'&&<CouponForm coupon={modal.coupon} onSave={data=>save('coupons.save',data,'Cupom salvo.')}/>}{modal.type==='expense'&&<ExpenseForm expense={modal.expense} onSave={data=>save('expenses.save',data,'Despesa salva.')}/>}{modal.type==='stock'&&<StockForm product={modal.product} variant={modal.variant} onSave={data=>save('inventory.adjust',data,'Estoque atualizado.')}/>}{modal.type==='category'&&<CategoryForm old={modal.old} onSave={data=>save('categories.save',data,'Categoria salva.')}/>}{modal.type==='categories'&&<><div className="ad-category-list">{state.categories.map(c=><div key={c}><span>{c}<small>{state.products.filter(p=>p.category===c).length} produtos</small></span><button className="ad-text-button" onClick={()=>setModal({type:'category',old:c})}>Editar</button><button className="ad-text-button danger-text" onClick={()=>setModal({type:'confirm',title:'Remover categoria?',text:c,action:()=>save('categories.delete',{name:c},'Categoria removida.')})}>Remover</button></div>)}</div><Button icon="plus" onClick={()=>setModal({type:'category'})}>Nova categoria</Button></>}{modal.type==='confirm'&&<Form label="Confirmar" onSubmit={modal.action}><p className="ad-confirm-text">{modal.text}</p></Form>}
 </Modal>}
 </div>;
}
function Metric({label,value,icon,note}){return <div className="ad-metric"><div><span>{label}</span><I name={icon} size={19}/></div><strong>{value}</strong><small>{note||'No período selecionado'}</small></div>;}
function RevenueChart({state,days}){const count=days===7?7:10;const values=Array(count).fill(0);const now=new Date();const from=new Date(now);from.setDate(from.getDate()-days+1);from.setHours(0,0,0,0);const step=days*86400000/count;state.orders.filter(o=>o.payment==='paid').forEach(o=>{const time=new Date(o.paidAt||o.createdAt)-from;const index=Math.floor(time/step);if(index>=0&&index<count)values[index]+=o.total;});const max=Math.max(...values,100);const points=values.map((v,i)=>`${40+i*(600/(count-1))},${180-(v/max)*145}`).join(' ');return <div className="ad-chart" role="img" aria-label={`Gráfico da receita paga nos últimos ${days} dias. Total: ${money(values.reduce((a,b)=>a+b,0))}.`}><svg viewBox="0 0 680 225" aria-hidden="true"><defs><linearGradient id="ad-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8bbe50" stopOpacity=".28"/><stop offset="100%" stopColor="#8bbe50" stopOpacity="0"/></linearGradient></defs>{[35,83,131,180].map(y=><line key={y} x1="40" x2="640" y1={y} y2={y} stroke="#ecede8" strokeDasharray="3 5"/>)}<polygon points={`40,180 ${points} 640,180`} fill="url(#ad-chart-fill)"/><polyline points={points} stroke="#729e42" strokeWidth="2.7" fill="none" strokeLinejoin="round"/>{values.map((v,i)=><g key={i}><circle cx={40+i*600/(count-1)} cy={180-v/max*145} r="3" fill="#729e42"/>{(i===0||i===count-1||i===Math.floor(count/2))&&<text x={40+i*600/(count-1)} y="212" textAnchor="middle" fill="#939a8b" fontSize="10">{dateLabel(new Date(from.getTime()+i*step).toISOString())}</text>}</g>)}</svg>{!values.some(Boolean)&&<span className="ad-chart-empty">Nenhum pagamento registrado neste período.</span>}</div>;}
function TopProducts({orders}){const map=new Map();orders.forEach(o=>o.items.forEach(i=>{const p=map.get(i.productId)||{name:i.name,qty:0,revenue:0};p.qty+=i.qty;p.revenue+=i.qty*i.unitPrice;map.set(i.productId,p);}));const rows=[...map.values()].sort((a,b)=>b.qty-a.qty).slice(0,10);return <div className="ad-table-wrap"><table className="ad-table"><thead><tr><th>Posição</th><th>Produto</th><th>Peças vendidas</th><th>Receita dos itens</th></tr></thead><tbody>{rows.map((p,i)=><tr key={i}><td><span className="ad-rank">{i+1}</span></td><td><strong>{p.name}</strong></td><td>{p.qty}</td><td>{money(p.revenue)}</td></tr>)}</tbody></table>{!rows.length&&<Empty icon="chart" title="Seu relatório começa nas vendas" text="As peças mais vendidas aparecerão após registrar pagamentos."/>}</div>;}
function SettingsForm({settings,onSave}){const [f,set]=useState(settings);const change=k=>e=>set({...f,[k]:e.target.value});return <Form onSubmit={()=>onSave({...f,lowStock:Number(f.lowStock)})}><Field label="Nome da loja *" value={f.name} onChange={change('name')} required/><div className="ad-form-row"><Field label="E-mail de contato" type="email" value={f.email} onChange={change('email')}/><Field label="Telefone / WhatsApp" value={f.phone} onChange={change('phone')}/></div><Field label="Instagram" type="url" value={f.instagram} onChange={change('instagram')}/><Field label="Endereço comercial"><textarea rows="3" value={f.address} onChange={change('address')}/></Field><Field label="Alertar quando o estoque chegar a" type="number" min="0" max="1000" step="1" value={f.lowStock} onChange={change('lowStock')} hint="O limite vale para cada combinação de tamanho e cor."/><div className="ad-tip"><I name="wallet"/><p>Checkout pelo WhatsApp: <strong>{window.__GRIFF_RUNTIME__?.checkoutWhatsApp || 'não configurado'}</strong>. Para trocar esse destino, é necessário atualizar a configuração publicada do site. Moeda: real brasileiro (BRL). Pagamentos e estornos são registros manuais de operações feitas fora do painel.</p></div></Form>;}
